const {Command} = require('commander');
const program = new Command();

program
    .name('Greet CLI');
    .description('This is a basic cli for the purpose of greeting someone');
    .version('1.0.0');

program
    .command('hello <name>');
    .description('say hello to someone');
    .action((name) => {
        console.log(`Hello ${name}`)
    })
